const char NANO_INFO_FOOT_BASED[] = "\"Based on\" as named by Neural DSP or the Unofficial Quad Cortex Device List. Product names are trademarks of their owners – no affiliation with this editor. Starting points are places to begin, not recipes.";
const char NANO_INFO_FOOT_LIKE[] = "\"In the style of\" names classic devices of the same kind for orientation – Neural DSP does not name an original for this model. Starting points are places to begin, not recipes.";
const char NANO_INFO_FOOT_PLAYERS[] = "Players' sounds: the pedal is the one the player is documented with. Where a note says \"read off\", the settings come from a photo of the player's board; otherwise they are our own reading of the records – places to begin. Names of players and bands only say whose sound a setting is modelled on; no affiliation or endorsement.";

const nano_info_t *nano_fx_info(uint32_t type)
{
    for (size_t i = 0; i < sizeof(INFO) / sizeof(INFO[0]); i++) {
        if (INFO[i].type == type) return &INFO[i];
    }
    return NULL;
}
